"""Phase 1b: convert a Viterbi state path into a list of gene dicts.

Handles both the strand HMM (10 states) and the joint HMM (19 states).
"""
from __future__ import annotations

from typing import Dict, List, Tuple

import numpy as np

from .hmm_prokaryotic import (
    CANONICAL_START_CODONS,
    ProkaryoticJointHMM as _JointHMM,
    ProkaryoticStrandHMM as _StrandHMM,
    STOP_CODONS,
)

_StrandHMMLike = _StrandHMM

VALID_START_SET = frozenset(CANONICAL_START_CODONS)
VALID_STOP_SET = frozenset(STOP_CODONS)


def _revcomp(s: str) -> str:
    tbl = {"A": "T", "T": "A", "C": "G", "G": "C", "N": "N"}
    return "".join(tbl.get(b, "N") for b in reversed(s.upper()))


def _strand_layout(hmm: _StrandHMMLike | None = None):
    cls = hmm if hmm is not None else _StrandHMM
    return (
        cls.START0,
        cls.START1,
        cls.START2,
        cls.CDS0,
        cls.CDS1,
        cls.CDS2,
        cls.STOP0,
        cls.STOP1,
        cls.STOP2,
        getattr(cls, "START_OVERLAP_4", -1),
        getattr(cls, "START_OVERLAP_7", -1),
        cls.NUM_STATES,
    )


def strand_path_to_genes(
    state_path: np.ndarray,
    strand: str,
    seq_name: str,
    sequence: str,
    offset: int = 0,
    hmm: _StrandHMMLike | None = None,
) -> List[Dict]:
    """Walk a (L,) strand-HMM Viterbi path and emit one dict per decoded gene.

    The sequence and ``state_path`` are assumed to already be oriented the way
    the HMM saw them (i.e. for the − strand, pass the reverse-complement
    sequence and the reversed NN probabilities, then un-reverse coordinates
    afterwards via ``offset`` + seq length).

    Returned dicts use **0-based half-open** [start, end) on the given
    orientation; caller converts to genomic coordinates.
    """
    S0, S1, S2, C0, C1, C2, Z0, Z1, Z2, O4, O7, num_states = _strand_layout(hmm)

    IN_GENE = tuple(s for s in (S0, S1, S2, C0, C1, C2, Z0, Z1, Z2, O4, O7) if s >= 0)
    in_gene_mask = np.zeros(num_states, dtype=bool)
    for s in IN_GENE:
        in_gene_mask[s] = True

    seq_u = sequence.upper()
    L = state_path.shape[0]
    genes: List[Dict] = []
    i = 0
    while i < L:
        if not in_gene_mask[int(state_path[i])]:
            i += 1
            continue
        # Scan until we hit a standard STOP2 terminus, or an overlap state that
        # serves as both the upstream stop base and downstream start base.
        j = i
        stop_end = -1
        next_i = -1
        while j < L and in_gene_mask[int(state_path[j])]:
            cur = int(state_path[j])
            prev = int(state_path[j - 1]) if j > i else -1
            if cur == Z2:
                stop_end = j + 1
                next_i = j + 1
                break
            if cur == O4 and prev == Z1:
                stop_end = j + 1
                next_i = j
                break
            if cur == O7 and prev == Z0:
                stop_end = j + 1
                next_i = j
                break
            j += 1
        if stop_end < 0:
            i = max(j, i + 1)
            continue

        gs = i
        ge = stop_end  # exclusive end
        length = ge - gs
        if length < 6 or ge - 3 < gs + 3 or ge > len(seq_u):
            # Must advance past the rejected terminus (overlap sets next_i=j).
            i = max(next_i + 1, j + 1, i + 1)
            continue

        start_codon = seq_u[gs:gs + 3]
        stop_codon = seq_u[ge - 3:ge]
        if start_codon not in VALID_START_SET or stop_codon not in VALID_STOP_SET:
            i = max(next_i + 1, j + 1, i + 1)
            continue
        genes.append({
            "seqid": seq_name,
            "strand": strand,
            "start": offset + gs,
            "end": offset + ge,
            "start_codon": start_codon,
            "stop_codon": stop_codon,
            "length": length,
        })
        i = next_i
    return genes


def minus_strand_decoded_to_forward(
    genes_on_rc: List[Dict],
    seq_len: int,
    seq_name: str,
) -> List[Dict]:
    """Convert gene intervals decoded on the RC sequence back into forward
    (genomic) coordinates and mark them as ``strand='-'``."""
    out: List[Dict] = []
    for g in genes_on_rc:
        s, e = g["start"], g["end"]
        fwd_s = seq_len - e
        fwd_e = seq_len - s
        out.append({
            "seqid": seq_name,
            "strand": "-",
            "start": fwd_s,
            "end": fwd_e,
            "start_codon": g["start_codon"],
            "stop_codon": g["stop_codon"],
            "length": g["length"],
        })
    return out


def joint_path_to_genes(
    state_path: np.ndarray,
    seq_name: str,
    sequence: str,
) -> Tuple[List[Dict], List[Dict]]:
    """Decode the 19-state joint HMM path into (plus_genes, minus_genes).

    The joint HMM visits + strand genes in biological 5'→3' order but − strand
    genes in biological 3'→5' order (because we traverse forward coords from
    low to high).
    """
    seq_u = sequence.upper()
    L = state_path.shape[0]

    plus_in = set([
        _JointHMM.S0P, _JointHMM.S1P, _JointHMM.S2P,
        _JointHMM.C0P, _JointHMM.C1P, _JointHMM.C2P,
        _JointHMM.Z0P, _JointHMM.Z1P, _JointHMM.Z2P,
    ])
    for s in (getattr(_JointHMM, "O4P", -1), getattr(_JointHMM, "O7P", -1)):
        if s >= 0:
            plus_in.add(s)
    minus_in = set([
        _JointHMM.S0M, _JointHMM.S1M, _JointHMM.S2M,
        _JointHMM.C0M, _JointHMM.C1M, _JointHMM.C2M,
        _JointHMM.Z0M, _JointHMM.Z1M, _JointHMM.Z2M,
    ])
    for s in (getattr(_JointHMM, "O4M", -1), getattr(_JointHMM, "O7M", -1)):
        if s >= 0:
            minus_in.add(s)

    genes_plus: List[Dict] = []
    genes_minus: List[Dict] = []

    i = 0
    while i < L:
        s = int(state_path[i])
        if s in plus_in:
            j = i
            stop_end = -1
            next_i = -1
            while j < L and int(state_path[j]) in plus_in:
                cur = int(state_path[j])
                prev = int(state_path[j - 1]) if j > i else -1
                if cur == _JointHMM.Z2P:
                    stop_end = j + 1
                    next_i = j + 1
                    break
                if cur == getattr(_JointHMM, "O4P", -2) and prev == _JointHMM.Z1P:
                    stop_end = j + 1
                    next_i = j
                    break
                if cur == getattr(_JointHMM, "O7P", -2) and prev == _JointHMM.Z0P:
                    stop_end = j + 1
                    next_i = j
                    break
                j += 1
            if stop_end >= 0 and stop_end - i >= 6 and stop_end <= L:
                gs, ge = i, stop_end
                start_codon = seq_u[gs:gs + 3]
                stop_codon = seq_u[ge - 3:ge]
                if start_codon in VALID_START_SET and stop_codon in VALID_STOP_SET:
                    genes_plus.append({
                        "seqid": seq_name,
                        "strand": "+",
                        "start": gs,
                        "end": ge,
                        "start_codon": start_codon,
                        "stop_codon": stop_codon,
                        "length": ge - gs,
                    })
            i = next_i if next_i >= 0 else j
        elif s in minus_in:
            j = i
            saw_start0 = False
            while j < L and int(state_path[j]) in minus_in:
                if int(state_path[j]) == _JointHMM.S0M:
                    saw_start0 = True
                    j += 1
                    break
                j += 1
            if saw_start0 and j - i >= 6 and j <= L:
                gs, ge = i, j
                # On the − strand the gene occupies forward positions [gs, ge).
                # The forward-strand STOP codon (which is the biological STOP
                # on − strand) occupies forward [gs, gs+3); the forward-strand
                # START codon RC is [ge-3, ge).
                fwd_stop_triplet = seq_u[gs:gs + 3]
                fwd_start_triplet = seq_u[ge - 3:ge]
                bio_start = _revcomp(fwd_start_triplet)
                bio_stop = _revcomp(fwd_stop_triplet)
                if bio_start in VALID_START_SET and bio_stop in VALID_STOP_SET:
                    genes_minus.append({
                        "seqid": seq_name,
                        "strand": "-",
                        "start": gs,
                        "end": ge,
                        "start_codon": bio_start,
                        "stop_codon": bio_stop,
                        "length": ge - gs,
                    })
            i = j
        else:
            i += 1

    return genes_plus, genes_minus


