def write_gff3(
    path: str,
    genes: List[Dict],
    source: str = "HelixerHMM",
) -> None:
    """Write a minimal GFF3 with one CDS feature per gene."""
    from pathlib import Path
    p = Path(path)
    p.parent.mkdir(parents=True, exist_ok=True)
    with open(p, "w") as fh:
        fh.write("##gff-version 3\n")
        genes_by_seq: Dict[str, List[Dict]] = {}
        for g in genes:
            genes_by_seq.setdefault(g["seqid"], []).append(g)
        gene_idx = 1
        for seqid in sorted(genes_by_seq.keys()):
            for g in sorted(genes_by_seq[seqid], key=lambda x: (x["start"], x["end"])):
                start = g["start"] + 1  # GFF 1-based inclusive
                end = g["end"]
                gid = f"gene_{gene_idx:06d}"
                attrs = (
                    f"ID={gid};start_codon={g['start_codon']};"
                    f"stop_codon={g['stop_codon']}"
                )
                fh.write(
                    f"{seqid}\t{source}\tCDS\t{start}\t{end}\t.\t{g['strand']}\t0\t{attrs}\n"
                )
                gene_idx += 1
